import { MeshBasicNodeMaterial, MeshStandardNodeMaterial, MeshPhysicalNodeMaterial } from 'three/webgpu';
import { uv, mix, color, vec2, vec3, smoothstep, float, texture, clamp } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Group, Mesh, PlaneGeometry, BoxGeometry, PointLight } = THREE;

  const spec = config.intent?.visualSpec ?? {};
  const colors = spec.colors ?? {};
  const C_BG = colors.background ?? '#0b0b10';
  const C_SURF = colors.surface ?? '#14141a';
  const C_INK = colors.ink ?? '#16161d';
  const C_PAPER = colors.paper ?? '#e8ecf2';
  const C_ACCENT = colors.accent ?? '#ff2a38';

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = items.find((i) => i.role === 'headline');
  const captionItems = items.filter((i) => i.role === 'caption');
  const headlineText = headlineItem ? headlineItem.text : 'Inside the atelier';
  const captionTexts = captionItems.length
    ? captionItems.map((i) => i.text)
    : ['DIAL ROOM', 'ESCAPEMENT BENCH', 'CNC HALL', 'FINISHING LAB', 'ARCHIVE VAULT', 'ASSEMBLY LINE ONE'];

  const group = new Group();
  const disposables = [];
  const timelines = [];
  const primResults = [];
  let loadedTex = null;

  // ---------- BACKDROP — full-frame graded stage (kills FLAT_VOID) ----------
  // At z=-2.6 the fov-50 frame is ~15.6 x 11.7 units; the plane must cover it.
  const backdropGeo = new PlaneGeometry(16, 12);
  const backdropMat = new MeshBasicNodeMaterial();
  {
    const u = uv();
    const grad = mix(color(C_BG), color(C_SURF), smoothstep(float(0.0), float(1.0), u.y));
    // warm-neutral lift behind the plate column
    const columnLift = smoothstep(float(0.4), float(0.0), u.sub(vec2(0.58, 0.5)).length()).mul(0.55);
    // second lift over the headline / index field on the left — no black half
    const leftLift = smoothstep(float(0.42), float(0.0), u.sub(vec2(0.3, 0.62)).length()).mul(0.4);
    // faint accent wash bleeding off the focused plate's lit edge (<10% accent)
    const accentWash = smoothstep(float(0.22), float(0.0), u.sub(vec2(0.52, 0.5)).length()).mul(0.09);
    backdropMat.colorNode = grad
      .add(color('#2b2925').mul(columnLift))
      .add(color('#262420').mul(leftLift))
      .add(color(C_ACCENT).mul(accentWash));
  }
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.6);
  group.add(backdrop);
  disposables.push(backdropGeo, backdropMat);

  // ---------- LOCAL LIGHTS — accent rim left, low neutral fill (no blowout) ----------
  const rim = new PointLight(C_ACCENT, 1.2, 8);
  rim.position.set(-1.4, 0.2, 1.2);
  group.add(rim);
  const fill = new PointLight(C_PAPER, 0.3, 10);
  fill.position.set(2.8, 2.0, 2.6);
  group.add(fill);

  // ---------- HEADLINE (pinned per spec) + accent rule ----------
  const headlineObj = ctx.fontAtlas.createText(headlineText, {
    fontSize: headlineItem?.typography?.fontSize ?? 68,
    color: C_PAPER,
    align: 'left',
  });
  headlineObj.position.set(-1.6, 1.9, 0.3);
  group.add(headlineObj);

  const ruleGeo = new PlaneGeometry(0.55, 0.022);
  const ruleMat = new MeshStandardNodeMaterial({
    color: C_ACCENT,
    emissive: C_ACCENT,
    emissiveIntensity: 1.1,
    roughness: 0.6,
    metalness: 0.1,
  });
  const rule = new Mesh(ruleGeo, ruleMat);
  rule.position.set(-1.325, 1.6, 0.3);
  group.add(rule);
  disposables.push(ruleGeo, ruleMat);

  // ---------- INDEX RAIL — fills the left field with spec copy ----------
  const railTexts = [];
  const railYs = [];
  for (let i = 0; i < captionTexts.length; i++) {
    const y = 1.0 - i * 0.34;
    railYs.push(y);
    const t = ctx.fontAtlas.createText(captionTexts[i], {
      fontSize: 15,
      color: C_PAPER,
      align: 'left',
      letterSpacingPx: 1.4,
    });
    t.position.set(-3.25, y, 0.15);
    t.traverse((o) => {
      if (o.material) { o.material.transparent = true; o.material.opacity = 0.42; }
    });
    group.add(t);
    railTexts.push(t);
  }
  const markerGeo = new PlaneGeometry(0.06, 0.06);
  const markerMat = new MeshStandardNodeMaterial({
    color: C_ACCENT,
    emissive: C_ACCENT,
    emissiveIntensity: 1.2,
    roughness: 0.6,
    metalness: 0.1,
  });
  const marker = new Mesh(markerGeo, markerMat);
  marker.position.set(-3.42, railYs[0], 0.15);
  group.add(marker);
  disposables.push(markerGeo, markerMat);

  // ---------- LOOP COLUMN ----------
  const COUNT = 6;
  const PITCH = 1.5;
  const LOOP = COUNT * PITCH;
  const column = new Group();
  column.position.set(0.9, 0, 0);
  group.add(column);

  const plateGeo = new PlaneGeometry(1.9, 1.2);
  const frameGeo = new BoxGeometry(1.96, 1.26, 0.06);
  const stripGeo = new PlaneGeometry(0.03, 1.2);
  disposables.push(plateGeo, frameGeo, stripGeo);

  // distinct crops + warm-neutral grades per plate
  const crops = [
    { r: 1.0,  x: 0.0,  y: 0.0,  tr: 1.0,  tg: 0.98, tb: 0.95, hx: 0.35, hy: 0.6,  gx: 0.7,  gy: 0.3 },
    { r: 0.8,  x: 0.1,  y: 0.15, tr: 0.96, tg: 0.95, tb: 0.93, hx: 0.6,  hy: 0.4,  gx: 0.3,  gy: 0.7 },
    { r: 0.72, x: 0.25, y: 0.05, tr: 1.0,  tg: 0.96, tb: 0.9,  hx: 0.5,  hy: 0.65, gx: 0.5,  gy: 0.5 },
    { r: 0.68, x: 0.02, y: 0.28, tr: 0.94, tg: 0.94, tb: 0.94, hx: 0.3,  hy: 0.35, gx: 0.8,  gy: 0.2 },
    { r: 0.65, x: 0.3,  y: 0.3,  tr: 1.0,  tg: 0.97, tb: 0.92, hx: 0.65, hy: 0.55, gx: 0.4,  gy: 0.6 },
    { r: 0.85, x: 0.12, y: 0.02, tr: 0.97, tg: 0.95, tb: 0.92, hx: 0.45, hy: 0.45, gx: 0.6,  gy: 0.4 },
  ];

  // filmic placeholder — reads as a graded photo, never flat gray or void
  function placeholderNode(i) {
    const c = crops[i];
    const u = uv();
    const diag = smoothstep(float(0.0), float(1.0), u.x.mul(float(c.gx)).add(u.y.mul(float(c.gy))));
    const base = mix(color('#1c1b19'), color('#4a443c'), diag);
    const hot = smoothstep(float(0.5), float(0.0), u.sub(vec2(c.hx, c.hy)).length());
    const vig = smoothstep(float(1.15), float(0.35), u.sub(vec2(0.5, 0.5)).length().mul(2.0));
    return base.add(color('#8a8176').mul(hot.mul(0.5))).mul(mix(float(0.45), float(1.0), vig));
  }

  // graded photograph — baked vignette + exposure ceiling (kills DEAD_LIGHTING blowout)
  function texturedNode(tex, i) {
    const c = crops[i];
    const u = uv();
    const cu = clamp(u.mul(float(c.r)).add(vec2(Math.min(c.x, 1 - c.r), Math.min(c.y, 1 - c.r))), float(0.0), float(1.0));
    const t = texture(tex, cu);
    const vig = smoothstep(float(1.2), float(0.32), u.sub(vec2(0.5, 0.5)).length().mul(2.0));
    return t.rgb.mul(vec3(c.tr, c.tg, c.tb)).mul(mix(float(0.5), float(0.88), vig));
  }

  const plates = [];
  for (let i = 0; i < COUNT; i++) {
    const holder = new Group();

    const frameMat = new MeshStandardNodeMaterial({
      color: C_INK,
      roughness: 0.5,
      metalness: 0.5,
    });
    const frame = new Mesh(frameGeo, frameMat);
    frame.position.z = -0.035;
    holder.add(frame);
    disposables.push(frameMat);

    const plateMat = new MeshPhysicalNodeMaterial({
      roughness: 0.6,
      metalness: 0.1,
      clearcoat: 0.1,
      clearcoatRoughness: 0.5,
    });
    plateMat.colorNode = placeholderNode(i);
    const plate = new Mesh(plateGeo, plateMat);
    plate.position.z = 0.002;
    holder.add(plate);
    disposables.push(plateMat);

    const stripMat = new MeshStandardNodeMaterial({
      color: C_ACCENT,
      emissive: C_ACCENT,
      emissiveIntensity: 1.4,
      roughness: 0.6,
      metalness: 0.1,
      transparent: true,
      opacity: 0,
    });
    const strip = new Mesh(stripGeo, stripMat);
    strip.position.set(-0.965, 0, 0.01);
    holder.add(strip);
    disposables.push(stripMat);

    column.add(holder);
    plates.push({ holder, plateMat, stripMat, idx: i });
  }

  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    loadedTex = tex;
    for (let i = 0; i < COUNT; i++) {
      plates[i].plateMat.colorNode = texturedNode(tex, i);
      plates[i].plateMat.needsUpdate = true;
    }
  }).catch(() => {});

  // ---------- FOCUSED CAPTIONS (fade at x=-1.6 per spec) ----------
  const captionGroups = [];
  for (let i = 0; i < COUNT; i++) {
    const cap = ctx.fontAtlas.createText(captionTexts[i % captionTexts.length], {
      fontSize: 18,
      color: C_PAPER,
      align: 'left',
      letterSpacingPx: 1.5,
    });
    cap.position.set(-1.6, -0.05, 0.3);
    cap.visible = false;
    const mats = [];
    cap.traverse((o) => {
      if (o.material) {
        o.material.transparent = true;
        o.material.opacity = 0;
        mats.push(o.material);
      }
    });
    group.add(cap);
    captionGroups.push({ obj: cap, mats });
  }

  // ---------- SCROLL STATE (weighted inertia, damping 0.12) ----------
  let target = 0;
  let current = 0;
  let focused = -1;

  function wrapY(baseY) {
    return ((baseY + current + LOOP / 2) % LOOP + LOOP) % LOOP - LOOP / 2;
  }

  function setFocus(i) {
    if (i === focused) return;
    if (focused >= 0) {
      const old = plates[focused];
      gsap.to(old.holder.scale, { x: 1, y: 1, z: 1, duration: 0.35, ease: 'power2.out' });
      gsap.to(old.stripMat, { opacity: 0, duration: 0.3, ease: 'power2.out' });
      const oc = captionGroups[focused];
      gsap.to(oc.mats, {
        opacity: 0,
        duration: 0.25,
        ease: 'power2.out',
        onComplete: () => { oc.obj.visible = false; },
      });
    }
    focused = i;
    if (i >= 0) {
      const nw = plates[i];
      gsap.to(nw.holder.scale, { x: 1.06, y: 1.06, z: 1.06, duration: 0.35, ease: 'power2.out' });
      gsap.to(nw.stripMat, { opacity: 1, duration: 0.35, ease: 'power2.out' });
      const nc = captionGroups[i];
      nc.obj.visible = true;
      nc.obj.position.y = -0.25;
      gsap.to(nc.obj.position, { y: -0.05, duration: 0.5, ease: 'power2.out' });
      gsap.to(nc.mats, { opacity: 1, duration: 0.4, ease: 'power2.out' });
      gsap.to(marker.position, { y: railYs[i % railYs.length], duration: 0.4, ease: 'power3.out' });
    }
  }

  const ticker = (t, deltaMS) => {
    const dt = Math.min(deltaMS / 1000, 0.05);
    target += 0.14 * dt; // single-axis idle cycle
    current += (target - current) * 0.12;
    let best = -1;
    let bestDist = Infinity;
    for (let i = 0; i < COUNT; i++) {
      const y = wrapY(i * PITCH);
      plates[i].holder.position.y = y;
      const d = Math.abs(y);
      if (d < bestDist) { bestDist = d; best = i; }
    }
    setFocus(best);
  };
  gsap.ticker.add(ticker);

  // ---------- ENTRANCE (rise-in + weighted-settle) ----------
  const enter = gsap.timeline();
  column.position.y = -0.4;
  enter.to(column.position, { y: 0, duration: 0.7, ease: 'power3.out' });
  enter.fromTo(column.scale, { x: 1.04, y: 1.04, z: 1.04 }, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }, '-=0.2');
  timelines.push(enter);

  // ---------- CINEMATIC PRIMITIVES (scoped to the column, not the whole stage) ----------
  const prims = config.cinematicPrimitives ?? [];
  for (const p of prims) {
    const fn = ctx.primitives[p.name];
    if (fn) primResults.push(fn(column, p.params ?? {}));
  }

  // ---------- HANDLERS ----------
  group.userData.handlers = {
    scroll: (e) => {
      if (e && typeof e.progress === 'number') {
        target = e.progress * LOOP;
      } else {
        const d = (e && (e.deltaY ?? e.delta ?? 0)) || 0;
        target += d * 0.0015 * PITCH;
      }
    },
  };

  // ---------- CLEANUP ----------
  group.userData.cleanup = () => {
    gsap.ticker.remove(ticker);
    for (const tl of timelines) tl.kill();
    gsap.killTweensOf(column.position);
    gsap.killTweensOf(column.scale);
    gsap.killTweensOf(marker.position);
    for (const p of plates) {
      gsap.killTweensOf(p.holder.scale);
      gsap.killTweensOf(p.stripMat);
    }
    for (const c of captionGroups) {
      gsap.killTweensOf(c.obj.position);
      gsap.killTweensOf(c.mats);
    }
    for (const r of primResults) { if (r && r.cleanup) r.cleanup(); }
    for (const d of disposables) { if (d.dispose) d.dispose(); }
    if (loadedTex && loadedTex.dispose) loadedTex.dispose();
  };

  return group;
}
